const raw = $json.choices?.[0]?.message?.content || $json.response || '';
let parsed;

try {
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  parsed = JSON.parse(raw.slice(start, end + 1));
} catch (e) {
  parsed = {
    tipo_incidente: 'sin_clasificar',
    intensidad: 'media',
    resumen_publico: 'Reporte transformado en arte generativo contra el racismo en el fútbol.',
    prompt_artistico: 'abstract generative artwork, resistance against racism in football, stadium lights, green field, hopeful energy, no text, no logos'
  };
}

return [{
  json: {
    ...$input.first().json,
    analisis: parsed,
    prompt_artistico: parsed.prompt_artistico
  }
}];

