const imageResponse = $input.first().json;
const parsed = $('Code - Parsear respuesta').first().json;

const rawUrl = imageResponse.choices?.[0]?.message?.images?.[0]?.image_url?.url || null;
const imageBase64 = rawUrl?.startsWith('data:') ? rawUrl.split(',')[1] : (imageResponse.data?.[0]?.b64_json || null);
const imageUrl = rawUrl && !rawUrl.startsWith('data:') ? rawUrl : null;

const obra = {
  id: 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => { const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); }),
  titulo: `Obra Cancha Viva - ${new Date().toISOString().slice(0, 10)}`,
  fecha: new Date().toISOString(),
  tipo_incidente: parsed.analisis?.tipo_incidente || 'sin_clasificar',
  intensidad: parsed.analisis?.intensidad || 'media',
  lugar: parsed.lugar || 'No especificado',
  resumen_publico: parsed.analisis?.resumen_publico || '',
  prompt_artistico: parsed.prompt_artistico || '',
  imagen_base64: imageBase64,
  imagen_url: imageUrl
};

return [{ json: obra }];
